		["Text"] = "ALLIANCE ASKERİ RÜTBELERİNEW_LINE OFFICERSNEW_LINE Grand MarshalNEW_LINE Field MarshalNEW_LINE MarshalNEW_LINE CommanderNEW_LINE Lieutenant CommanderNEW_LINE Knight-ChampionNEW_LINE Knight-CaptainNEW_LINE Knight-LieutenantNEW_LINE KnightNEW_LINE ENLISTEDNEW_LINE Sergeant MajorNEW_LINE Master SergeantNEW_LINE SergeantNEW_LINE CorporalNEW_LINE Private"
