	["Marshal McBride's Documents"] = {
		["Title"] = "Marshal McBride's Documents",
		["Text"] = "REPORT: Kobolds\n\nThe activity of kobolds has increased in the vicinity of Northshire Valley.  They camp north of the abbey and within the Echo Ridge Mine in alarming numbers.  I have marshalled paladins, warriors and other local folk to aid me in ridding us of the vermin.\n\nThis progresses well.  And I will update as needed."
	},
	["Stormwind Armor Marker"] = {
		["Title"] = "Stormwind Armor Marker",
		["Text"] = "This Armor Marker is good for one piece of leather or cloth armor, redeemable at the Timberlain household within the Eastvale Logging Camp."
	},
	["William's Shipment"] = {
		["Title"] = "William's Shipment",
		["Text"] = "Hello Morgan,\n\nBusiness in Goldshire is brisk, so brisk that I haven't had time to send you any shipments!  \n\nI commissioned the person bearing this note to bring you a package of large wax candles (you know, the ones the Kobolds like to wear on their heads?). \n\nPlease give this person our thanks, and fair payment."
	},
